INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Simple vs complex capital structure definition
(2, 'Earnings Per Share', 'Under ASC 260, what distinguishes a complex capital structure from a simple capital structure?', '["A complex capital structure includes securities that could potentially dilute EPS", "A complex capital structure has more than one class of common stock outstanding", "A complex capital structure requires more than 1,000,000 shares outstanding", "A complex capital structure has both common and preferred stock outstanding"]'::jsonb, 0, 'Under ASC 260-10-15, a complex capital structure exists when an entity has outstanding securities that could potentially dilute basic EPS, such as convertible bonds, stock options, or warrants. A simple capital structure has no such potentially dilutive securities. Having preferred stock alone (choice D) does not create a complex capital structure unless the preferred is convertible into common shares.', 'easy', 1),

-- Q2: medium / L3 — Stock split after year-end retroactive adjustment
(2, 'Earnings Per Share', 'Belmont Industries reports basic EPS of $3.20 for the year ended December 31, 2025, based on 500,000 weighted-average shares. On February 10, 2026, before the financial statements are issued, the company declares a 2-for-1 stock split. What is the effect on reported EPS for the year ended December 31, 2025?', '["Basic EPS remains $3.20 because the split occurred after year-end", "Basic EPS is adjusted only in the 2026 comparative presentation", "Basic EPS is adjusted to $1.60 only if the stock split is disclosed in the notes", "Basic EPS must be retroactively adjusted to $1.60 based on 1,000,000 shares"]'::jsonb, 3, 'Under ASC 260-10-55-12, stock splits and stock dividends occurring after the balance sheet date but before financial statements are issued must be given retroactive effect in the EPS computation for all periods presented. The weighted-average shares are restated to 1,000,000, producing basic EPS of $1.60. Choice A is incorrect because ASC 260 requires retroactive adjustment even for post-period stock splits before issuance.', 'medium', 3),

-- Q3: easy / L1 — Dual EPS presentation requirement
(2, 'Earnings Per Share', 'Under U.S. GAAP, which entities are required to present both basic and diluted EPS on the face of the income statement?', '["All entities regardless of size", "Only entities with complex capital structures", "Public entities with common stock or potential common stock traded on a public market", "All entities that have net income exceeding $1 million"]'::jsonb, 2, 'Under ASC 260-10-15-2, EPS presentation is required for public entities—those with common stock or potential common stock traded in public markets. Nonpublic entities are not required to present EPS, though they may do so voluntarily. Choice A is incorrect because private companies are exempt from EPS presentation requirements under ASC 260.', 'easy', 1),

-- Q4: medium / L2 — Weighted-average with treasury stock repurchase mid-year
(2, 'Earnings Per Share', 'Clayfield Corp. has 300,000 shares of common stock outstanding on January 1, 2025. On September 1, the company repurchases 60,000 shares as treasury stock. No other share transactions occur. What is the weighted-average number of common shares outstanding for 2025?', '["240,000", "280,000", "260,000", "300,000"]'::jsonb, 1, 'Under ASC 260-10-45-10, treasury shares are excluded from the weighted-average computation from the date of repurchase. The calculation is: (300,000 x 8/12) + (240,000 x 4/12) = 200,000 + 80,000 = 280,000. Choice A (240,000) incorrectly treats the repurchase as occurring on January 1, removing all 60,000 shares for the entire year.', 'medium', 2),

-- Q5: easy / L1 — Numerator definition (earnings available to common)
(2, 'Earnings Per Share', 'In the basic EPS formula, what does the numerator represent?', '["Net income before taxes", "Net income plus preferred dividends", "Net income attributable to common stockholders", "Comprehensive income minus preferred dividends"]'::jsonb, 2, 'Under ASC 260-10-45-10, basic EPS is computed by dividing income available to common stockholders (net income minus preferred dividends) by the weighted-average common shares outstanding. The numerator represents net income attributable to common stockholders. Choice B is incorrect because preferred dividends are subtracted from, not added to, net income.', 'easy', 1),

-- Q6: medium / L3 — Participating securities and the two-class method
(2, 'Earnings Per Share', 'Glenmore Financial Corp. has 200,000 common shares and 50,000 shares of participating preferred stock outstanding. The preferred shares participate in dividends with common shares on a 1:1 basis after receiving their $2 per share base dividend. Net income is $750,000 and the base preferred dividend of $100,000 is declared. Under ASC 260, how does the existence of participating securities affect the computation of basic EPS?', '["Undistributed earnings must be allocated between common and participating preferred shares using the two-class method", "Participating preferred dividends are simply deducted from net income like nonparticipating preferred", "Participating preferred shares are included only in the diluted EPS denominator", "Undistributed earnings are allocated entirely to common shareholders since preferred already received their base dividend"]'::jsonb, 0, 'Under ASC 260-10-45-61A, participating securities require the two-class method for basic EPS. Undistributed earnings are allocated between common and participating preferred based on their respective rights to share in earnings. Choice D is incorrect because participating preferred shares have the right to share in undistributed earnings beyond their base dividend.', 'medium', 3),

-- Q7: medium / L2 — Convertible preferred if-converted method calculation
(2, 'Earnings Per Share', 'Ridgeway Holdings has net income of $900,000 and 250,000 weighted-average common shares outstanding. The company has 10,000 shares of $50 par, 8% convertible preferred stock, each convertible into 3 common shares. Preferred dividends of $40,000 were declared. Using the if-converted method, what is diluted EPS?', '["$3.44", "$3.21", "$3.60", "$3.00"]'::jsonb, 1, 'Under ASC 260-10-45-40, the if-converted method for convertible preferred stock adds back declared preferred dividends ($40,000) to the numerator and adds the potential shares (10,000 x 3 = 30,000) to the denominator. Diluted EPS = $900,000 / 280,000 = $3.21. Since this is less than basic EPS of $3.44, the conversion is dilutive. Choice A ($3.44) reflects basic EPS only, without considering the dilutive effect of the convertible preferred.', 'medium', 2),

-- Q8: easy / L1 — EPS line item presentation requirements
(2, 'Earnings Per Share', 'Under ASC 260, for which line items must per-share amounts be presented on the face of the income statement?', '["Only net income per share", "Gross profit, operating income, and net income per share", "Revenue, operating income, and net income per share", "Income from continuing operations and net income per share"]'::jsonb, 3, 'Under ASC 260-10-45-2, entities must present per-share amounts for income from continuing operations and net income on the face of the income statement. If discontinued operations are reported, per-share amounts for discontinued operations must also be presented either on the face or in the notes. Choice A is incorrect because EPS for income from continuing operations is also required, not just net income.', 'easy', 1),

-- Q9: medium / L3 — Antidilutive convertible bonds analysis
(2, 'Earnings Per Share', 'Harmon Manufacturing has basic EPS of $2.50 based on net income of $500,000 and 200,000 weighted-average shares. The company has $1,000,000 face value, 12% convertible bonds (each $1,000 bond convertible into 15 shares). The tax rate is 25%. What is the per-share impact of the convertible bonds, and should they be included in diluted EPS?', '["Per-share impact of $6.00; exclude because it is antidilutive", "Per-share impact of $4.50; include because it is dilutive", "Per-share impact of $8.00; exclude because the coupon rate is too high", "Per-share impact of $6.00; include because all convertible bonds must be included"]'::jsonb, 0, 'Under ASC 260-10-45-40, the if-converted method adds after-tax interest savings ($120,000 x 0.75 = $90,000) to the numerator and potential shares (1,000 bonds x 15 = 15,000) to the denominator. The per-share impact is $90,000 / 15,000 = $6.00. Since $6.00 exceeds basic EPS of $2.50, inclusion would increase EPS, making the bonds antidilutive. Choice D incorrectly includes the bonds despite their antidilutive effect.', 'medium', 3),

-- Q10: medium / L3 — Contingently issuable shares where condition is NOT met
(2, 'Earnings Per Share', 'Pemberton Corp. has a contingent share agreement that requires issuing 25,000 additional shares to former owners of an acquired company if cumulative revenue exceeds $50 million within three years. At December 31, 2025, cumulative revenue is $38 million with one year remaining. Under ASC 260, how should these contingent shares be treated in the EPS computation?', '["Include in both basic and diluted EPS because the shares may eventually be issued", "Include in diluted EPS only if the contingency condition would have been satisfied using year-end amounts as the assumed level of attainment", "Include in basic EPS only because the agreement creates a present obligation", "Exclude from both basic and diluted EPS because the condition has not been met"]'::jsonb, 1, 'Under ASC 260-10-45-48, contingently issuable shares are included in basic EPS only if all conditions are met by period-end. For diluted EPS, contingently issuable shares are included if the contingency condition would be satisfied assuming the end of the reporting period is the end of the contingency period. Choice D is incorrect because while the shares are excluded from basic EPS, they may be included in diluted EPS based on the period-end test.', 'medium', 3),

-- Q11: easy / L1 — Treasury stock method definition
(2, 'Earnings Per Share', 'Under ASC 260, what method is used to determine the dilutive effect of stock options and warrants on earnings per share?', '["The if-converted method", "The weighted-average method", "The treasury stock method", "The effective interest method"]'::jsonb, 2, 'Under ASC 260-10-45-22, the treasury stock method is used to compute the dilutive effect of stock options and warrants on EPS. This method assumes the options are exercised at the beginning of the period, the proceeds are used to repurchase shares at the average market price, and only the incremental net shares are added to the denominator. Choice A is incorrect because the if-converted method applies to convertible securities, not options and warrants.', 'easy', 1),

-- Q12: medium / L2 — Restricted stock units (RSUs) and EPS treatment
(2, 'Earnings Per Share', 'Pinecrest Technologies granted 20,000 restricted stock units (RSUs) to employees on January 1, 2025. The RSUs vest ratably over four years with no performance conditions. Net income is $1,200,000 and weighted-average shares outstanding are 400,000. Under ASC 260, how are the unvested RSUs treated for diluted EPS purposes?', '["All 20,000 shares are included in the diluted EPS denominator immediately upon grant", "The unvested RSUs are treated as contingently issuable shares and excluded until vested", "The unvested RSUs are included using the treasury stock method, with assumed proceeds equal to the unamortized compensation cost", "The RSUs are ignored for EPS purposes until the shares are actually issued"]'::jsonb, 2, 'Under ASC 260-10-45-28A, unvested share-based payment awards with service-only conditions are treated as potential common shares using the treasury stock method. The assumed proceeds include unamortized compensation cost, which is used to calculate the hypothetical share repurchase. Choice A is incorrect because the full grant is not added to the denominator; only the incremental dilutive shares after applying the treasury stock method are included.', 'medium', 2),

-- Q13: medium / L3 — Loss from continuing operations as control number
(2, 'Earnings Per Share', 'Waverly Systems reports a net loss from continuing operations of $180,000 and income from discontinued operations (net of tax) of $60,000. The company has 100,000 weighted-average shares outstanding, 5,000 dilutive stock options, and 2,000 shares of convertible preferred stock convertible into 8,000 common shares. What is the effect on the diluted EPS computation?', '["Both the options and convertible preferred are included because discontinued operations generate income", "Only the stock options are included because they have no numerator impact", "The convertible preferred is included but options are excluded because they are more dilutive", "All potentially dilutive securities are excluded because there is a loss from continuing operations"]'::jsonb, 3, 'Under ASC 260-10-45-19, if an entity reports a loss from continuing operations, all potentially dilutive securities are antidilutive and must be excluded from diluted EPS, even if there is income from discontinued operations. The control number for determining dilution is the loss from continuing operations. Choice A is incorrect because the discontinued operations income does not override the antidilutive determination.', 'medium', 3),

-- Q14: hard / L4 — Sequential testing with individually dilutive but incrementally antidilutive security
(2, 'Earnings Per Share', 'Crestview Dynamics reports net income of $720,000 with 200,000 weighted-average common shares and $20,000 in preferred dividends (basic EPS = $3.50). The company has two potentially dilutive securities: (1) 8,000 stock options with an exercise price of $30 when the average market price is $50, producing 3,200 incremental shares; and (2) $500,000 of 10% convertible bonds (tax rate 25%), each $1,000 bond convertible into 8 shares. The CFO asks whether including both securities produces the most conservative result. Evaluate the correct approach under ASC 260.', '["Include only the stock options; the convertible bonds are antidilutive when tested incrementally after including the options", "Include both securities because each is individually dilutive when tested in isolation", "Exclude both securities because their combined effect is antidilutive", "Include only the convertible bonds because they have a larger numerator impact than the options"]'::jsonb, 0, 'Under ASC 260-10-45-21, securities must be tested sequentially from most to least dilutive. Stock options (zero numerator impact) are tested first, reducing EPS to $700,000 / 203,200 = $3.44. The convertible bonds have a per-share impact of $9.375 ($37,500 / 4,000), which exceeds $3.44, making them antidilutive on an incremental basis. Choice B is incorrect because ASC 260 requires sequential testing; a security individually dilutive may be antidilutive when tested incrementally.', 'hard', 4),

-- Q15: medium / L2 — Shares issued for services (non-cash)
(2, 'Earnings Per Share', 'On April 1, 2025, Bridgewater Consulting issues 12,000 shares of common stock to a law firm as payment for services valued at $180,000. Bridgewater had 200,000 shares outstanding on January 1 and no other share transactions during the year. What is the weighted-average number of shares for 2025?', '["200,000", "209,000", "203,000", "212,000"]'::jsonb, 1, 'Under ASC 260-10-45-10, shares issued for non-cash consideration are included in the weighted-average from the date of issuance. The 12,000 shares issued on April 1 are weighted for 9 months: (200,000 x 3/12) + (212,000 x 9/12) = 50,000 + 159,000 = 209,000. Choice D (212,000) incorrectly treats the shares as outstanding for the entire year, ignoring the issuance date.', 'medium', 2),

-- Q16: easy / L1 — Treasury stock method proceeds usage
(2, 'Earnings Per Share', 'In the treasury stock method used for diluted EPS, what are the assumed proceeds from the hypothetical exercise of stock options used for?', '["Reducing the net income numerator", "Paying off the entity''s outstanding debt", "Increasing the exercise price of the options", "Repurchasing common shares at the average market price"]'::jsonb, 3, 'Under ASC 260-10-45-23, the treasury stock method assumes that proceeds received from the hypothetical exercise of options are used to repurchase common shares at the average market price during the period. Only the excess of shares issued over shares repurchased (incremental shares) is added to the denominator. Choice A is incorrect because the treasury stock method affects only the denominator, not the numerator.', 'easy', 1),

-- Q17: medium / L3 — Rights issue bonus element and prior-period adjustment
(2, 'Earnings Per Share', 'Ferndale Corp. has 500,000 shares outstanding and announces a rights offering allowing shareholders to purchase one new share for every five held at $20 per share, when the market price is $35. The rights are exercised on June 1, 2025. What is the most likely effect on the EPS computation for 2025 and prior comparative periods?', '["The weighted-average shares for all periods presented must be adjusted for the bonus element inherent in the below-market rights offering", "Only the 100,000 new shares are included in the weighted-average from June 1 forward, with no adjustment to prior periods", "The entire 600,000 shares are used for all periods because rights offerings are treated like stock dividends", "Prior period EPS is not restated because the rights offering was for cash consideration"]'::jsonb, 0, 'Under ASC 260-10-55-20 through 55-27, when rights are issued at a price below fair value, the offering contains a bonus element similar to a stock dividend. The weighted-average shares for all periods presented must be adjusted by a factor reflecting this bonus element (market price / theoretical ex-rights price). Choice B is incorrect because ignoring the bonus element would overstate prior-period EPS relative to the current period.', 'medium', 3),

-- Q18: medium / L2 — Shares issued in a business combination
(2, 'Earnings Per Share', 'On August 1, 2025, Graystone Industries acquires Marker Solutions in a stock-for-stock business combination, issuing 80,000 shares to Marker''s shareholders. Graystone had 400,000 shares outstanding on January 1, 2025, and no other share transactions occurred during the year. What is Graystone''s weighted-average number of shares for 2025?', '["480,000", "433,333", "440,000", "400,000"]'::jsonb, 1, 'Under ASC 260-10-45-10, shares issued in a business combination are included in the weighted-average from the acquisition date. The calculation is (400,000 x 7/12) + (480,000 x 5/12) = 233,333 + 200,000 = 433,333. Choice A (480,000) incorrectly includes all 80,000 shares for the full year, which would overstate the denominator and understate EPS for the pre-acquisition period.', 'medium', 2),

-- Q19: medium / L2 — At-the-money options produce zero incremental shares
(2, 'Earnings Per Share', 'Aldridge Inc. has 150,000 weighted-average shares outstanding and net income of $450,000. The company has 10,000 stock options outstanding with an exercise price of $35 per share. The average market price of Aldridge''s common stock during the year was $35 per share. Under the treasury stock method, how many incremental shares are added for diluted EPS?', '["10,000 shares", "5,000 shares", "Zero shares", "3,500 shares"]'::jsonb, 2, 'Under ASC 260-10-45-22, the treasury stock method assumes options are exercised and the proceeds are used to repurchase shares at the average market price. When the exercise price equals the average market price ($35 = $35), the proceeds would repurchase all 10,000 shares, resulting in zero incremental shares. Choice A is incorrect because it assumes all option shares are added without considering the share repurchase component.', 'medium', 2),

-- Q20: hard / L3 — Forward purchase contract and reverse treasury stock method
(2, 'Earnings Per Share', 'Dunmore Corp. enters into a forward contract obligating it to repurchase 20,000 of its own shares at $60 per share in six months. The average market price during the period is $48 per share, and Dunmore has net income of $1,500,000 with 500,000 weighted-average shares outstanding. What is the effect of the forward purchase contract on diluted EPS under ASC 260?', '["The contract has no effect because the shares have not yet been repurchased", "The contract reduces the denominator by 20,000 shares because the entity is obligated to retire them", "The contract is excluded because forward contracts are always antidilutive", "The contract adds approximately 5,000 incremental shares to the denominator, reducing diluted EPS"]'::jsonb, 3, 'Under ASC 260-10-45-35, when an entity has a forward contract to repurchase its own shares at a price exceeding the average market price, the contract is dilutive. Using the reverse treasury stock method, the entity is assumed to issue shares at $48 to fund the repurchase (20,000 x $60 = $1,200,000 / $48 = 25,000 shares issued, minus 20,000 retired = 5,000 incremental shares). Choice C is incorrect because forward contracts with a repurchase price above market price are dilutive.', 'hard', 3),

-- Q21: medium / L2 — Share buyback program with multiple repurchase dates
(2, 'Earnings Per Share', 'Kelton Industries has 400,000 shares outstanding on January 1, 2025, and net income of $1,600,000 with $80,000 in preferred dividends. On May 1, Kelton repurchases 48,000 shares under a buyback program, and on November 1, it repurchases another 24,000 shares. What is basic EPS for 2025?', '["$3.80", "$4.00", "$4.63", "$4.18"]'::jsonb, 3, 'Under ASC 260-10-45-10, shares repurchased are removed from the weighted-average from the date of repurchase. Weighted-average: (400,000 x 4/12) + (352,000 x 6/12) + (328,000 x 2/12) = 133,333 + 176,000 + 54,667 = 364,000. Basic EPS = ($1,600,000 - $80,000) / 364,000 = $4.18. Choice A ($3.80) incorrectly uses the original 400,000 shares without adjusting for the buybacks.', 'medium', 2),

-- Q22: hard / L4 — Participating convertible preferred: evaluate two-class vs if-converted
(2, 'Earnings Per Share', 'Oakmont Financial has 300,000 common shares and 40,000 shares of convertible participating preferred stock outstanding. Each preferred share is convertible into 2 common shares and participates equally in dividends with common stock after receiving a $3 per share base dividend. Net income is $1,200,000 and $120,000 in base preferred dividends were declared. The CFO must determine whether to use the two-class method or the if-converted method. Evaluate the appropriate approach under ASC 260.', '["Use the two-class method for basic EPS and the if-converted method for diluted EPS, reporting the more dilutive result for each presentation", "Use only the if-converted method for both basic and diluted EPS because conversion is the primary dilutive feature", "Use the two-class method for both basic and diluted EPS because participation rights override conversion features", "Use the if-converted method for basic EPS and the two-class method for diluted EPS to maximize comparability"]'::jsonb, 0, 'Under ASC 260-10-45-60A, when a security is both convertible and participating, the entity must compute EPS under both the two-class method and the if-converted method, then report the more dilutive result for each of basic and diluted EPS. Choice B is incorrect because ASC 260 does not permit ignoring participation rights; both methods must be evaluated and the more dilutive outcome reported.', 'hard', 4),

-- Q23: hard / L4 — Written put options and reverse treasury stock method
(2, 'Earnings Per Share', 'Stonebridge Corp. writes a put option giving the holder the right to sell 15,000 shares of Stonebridge''s common stock to the company at $55 per share. The average market price is $42 per share during the period. Stonebridge has 500,000 weighted-average shares outstanding and net income of $2,000,000. Recommend the correct treatment of this written put option in diluted EPS under ASC 260.', '["Exclude the written put because put options are never included in diluted EPS", "Include the put by subtracting 15,000 shares from the denominator because the entity may repurchase them", "Include the put as dilutive, adding approximately 4,643 incremental shares using the reverse treasury stock method", "Include the put only if the option is exercised before the financial statements are issued"]'::jsonb, 2, 'Under ASC 260-10-45-35, written put options that are in the money (exercise price exceeds average market price) are dilutive. Using the reverse treasury stock method, the entity is assumed to issue shares at $42 to fund the $825,000 repurchase ($55 x 15,000), requiring 19,643 shares. After retiring 15,000 shares, 4,643 net incremental shares are added to the denominator. Choice A is incorrect because in-the-money written puts must be included in diluted EPS.', 'hard', 4),

-- Q24: medium / L2 — Interest savings net-of-tax for convertible bonds
(2, 'Earnings Per Share', 'Mercer Holdings has $2,000,000 of 5% convertible bonds outstanding. Each $1,000 bond is convertible into 20 shares of common stock. The corporate tax rate is 25%. When computing diluted EPS using the if-converted method, what amount is added to the numerator for these bonds?', '["$75,000", "$100,000", "$50,000", "$25,000"]'::jsonb, 0, 'Under ASC 260-10-45-40, the if-converted method adds the after-tax interest expense to the numerator because, if the bonds were converted, interest would no longer be paid and the related tax deduction would be lost. The after-tax adjustment is $100,000 x (1 - 0.25) = $75,000. Choice B ($100,000) is incorrect because it uses the pre-tax interest amount without adjusting for the $25,000 tax benefit that would also be eliminated.', 'medium', 2),

-- Q25: medium / L3 — Interim period EPS and year-to-date control number
(2, 'Earnings Per Share', 'Northfield Corp. reports net income of $200,000 for Q1 2025, a net loss of $50,000 for Q2, and net income of $300,000 for Q3. The company has 100,000 shares outstanding and 5,000 dilutive stock options. Analyze how the quarterly loss affects the inclusion of potentially dilutive securities in the year-to-date diluted EPS through September 30, 2025.', '["The stock options are excluded from diluted EPS for all three quarters because Q2 had a net loss", "The stock options are included in year-to-date diluted EPS through September 30 because year-to-date income from continuing operations is positive", "The stock options are included only in Q1 and Q3 diluted EPS and excluded from Q2", "The stock options are excluded from Q2 and from all subsequent quarters"]'::jsonb, 1, 'Under ASC 260-10-45-19 and ASC 270-10-45, year-to-date diluted EPS is computed independently using year-to-date income from continuing operations as the control number. Since the year-to-date income through September 30 is $450,000 (positive), the stock options are potentially dilutive and should be included. Choice A is incorrect because a loss in an individual quarter does not cause exclusion from the year-to-date calculation when cumulative income is positive.', 'medium', 3),

-- Q26: hard / L4 — Multiple classes of common stock EPS
(2, 'Earnings Per Share', 'Ashford Holdings has two classes of common stock: Class A (400,000 shares, one vote per share, $1.00 dividend per share) and Class B (100,000 shares, ten votes per share, $0.50 dividend per share). Net income is $900,000 and total declared dividends are $450,000 ($400,000 to Class A, $50,000 to Class B). Under ASC 260, evaluate the correct approach for computing basic EPS for each class.', '["Use the two-class method, allocating undistributed earnings based on each class''s contractual participation rights", "Combine both classes into a single weighted-average denominator of 500,000 shares and compute a single EPS figure", "Compute EPS only for Class A because Class B has a different dividend rate", "Allocate all net income equally on a per-share basis without distinguishing between distributed and undistributed earnings"]'::jsonb, 0, 'Under ASC 260-10-45-59B, entities with multiple classes of common stock must use the two-class method, allocating distributed earnings based on actual dividends declared and undistributed earnings based on each class''s contractual participation rights, producing separate EPS figures for each class. Choice B is incorrect because combining both classes into a single denominator ignores different dividend and participation rights, misstating per-share earnings.', 'hard', 4),

-- Q27: easy / L1 — Why weighted-average shares are used
(2, 'Earnings Per Share', 'Why does the EPS computation use weighted-average shares outstanding rather than end-of-period shares?', '["End-of-period shares are more difficult to calculate", "Weighted-average shares reflect the time period during which shares were available to generate earnings", "The SEC prohibits using end-of-period shares in EPS calculations", "Weighted-average shares always produce a lower EPS than end-of-period shares"]'::jsonb, 1, 'Under ASC 260-10-45-10, weighted-average shares are used because they reflect the portion of the period during which each share was outstanding and thus able to generate earnings. This approach provides a more meaningful relationship between earnings and the shares that produced them. Choice D is incorrect because weighted-average shares can be either higher or lower than end-of-period shares depending on share transactions during the year.', 'easy', 1),

-- Q28: hard / L4 — Performance-based PSUs and period-end test vs probability
(2, 'Earnings Per Share', 'Vanguard Systems grants 30,000 performance-based restricted stock units (PSUs) on January 1, 2025, that cliff vest in three years only if cumulative revenue exceeds $100 million. At December 31, 2025, cumulative revenue is $28 million and management estimates it is probable the target will be met. The average unamortized compensation cost per PSU is $18 and the average market price is $45 per share. Evaluate the correct treatment of these PSUs in Vanguard''s 2025 diluted EPS computation.', '["Include the PSUs using the treasury stock method because management estimates the performance condition is probable of being satisfied", "Include all 30,000 PSUs directly in the denominator because the award is probable of vesting", "Exclude the PSUs because the revenue condition would not be satisfied if the end of the reporting period were the end of the contingency period", "Include a proportionate number based on progress toward the revenue goal (28% of 30,000 = 8,400 shares)"]'::jsonb, 2, 'Under ASC 260-10-45-48, performance-based contingently issuable shares are included in diluted EPS only if the performance condition would be satisfied assuming the end of the reporting period is the end of the contingency period. Cumulative revenue of $28 million falls short of the $100 million target, so the PSUs are excluded. Management''s ASC 718 probability assessment for expense recognition does not override the ASC 260 period-end test. Choice A incorrectly conflates the expense recognition threshold with EPS inclusion criteria.', 'hard', 4),

-- Q29: easy / L1 — Antidilutive security definition
(2, 'Earnings Per Share', 'Under ASC 260, what is an antidilutive security?', '["A security that decreases the number of shares outstanding when exercised", "A security that has been retired or repurchased by the issuing entity", "A security with an exercise price higher than par value", "A security whose inclusion in the diluted EPS computation would increase EPS or decrease loss per share"]'::jsonb, 3, 'Under ASC 260-10-20, an antidilutive security is one whose inclusion in the diluted EPS computation would increase EPS or decrease the loss per share. Antidilutive securities are excluded from diluted EPS because their inclusion would make reported results appear more favorable than basic EPS. Choice C is incorrect because the relationship of exercise price to par value is irrelevant; the key comparison is the per-share impact relative to basic EPS.', 'easy', 1),

-- Q30: easy / L2 — Stock dividend retroactive adjustment to EPS
(2, 'Earnings Per Share', 'Prescott Manufacturing had 240,000 shares outstanding on January 1, 2025. On September 1, the company declared a 25% stock dividend, distributing 60,000 additional shares. Net income for 2025 was $900,000 with no preferred stock outstanding. What is basic EPS for 2025?', '["$3.75", "$3.46", "$3.00", "$2.40"]'::jsonb, 2, 'Under ASC 260-10-55-12, stock dividends are given retroactive effect in the EPS computation as if they occurred at the beginning of the earliest period presented. The weighted-average shares are 240,000 x 1.25 = 300,000 for the entire year, yielding basic EPS of $900,000 / 300,000 = $3.00. Choice B ($3.46) incorrectly weights the stock dividend from September 1 as if it were a regular share issuance rather than applying retroactive adjustment.', 'easy', 2)
;

COMMIT;
